        load_dotenv=bool(global_cfg.get("load_dotenv", False)),
        strict_env=bool(global_cfg.get("strict_env", False)),
        warn_timeout=str(global_cfg.get("warn_timeout", "5s")),
        hide_env_diff=bool(global_cfg.get("hide_env_diff", False)),
        log_format=global_cfg.get("log_format"),
        log_filter=global_cfg.get("log_filter"),
        whitelist_prefix=prefix_entries,
        whitelist_exact=exact_entries,
    )


def read_template() -> str:
    candidates = [
        self_path().with_name("stdlib_template.sh"),
        Path(__file__).resolve().with_name("stdlib_template.sh"),
        Path("/workspace/src/stdlib_template.sh"),
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate.read_text(encoding="utf-8")
    raise CLIError("stdlib_template.sh not found")


def render_stdlib() -> str:
    rendered = read_template()
    escaped = str(self_path()).replace("\\", "\\\\").replace('"', '\\"')
    return rendered.replace("__DIRENV_EXECUTABLE__", escaped)


def path_for_arg(arg: str | None) -> Path | None:
    if arg is None:
        return None
    path = Path(arg).expanduser()
    if not path.is_absolute():
        path = Path.cwd() / path
    return path.resolve(strict=False)


def pick_rc_in_dir(directory: Path, cfg: Config) -> Path | None:
    envrc = directory / ".envrc"
    if envrc.exists():
        return envrc.resolve()

_direnv_hook() {
  local previous_exit_status=$?;
  vars="$("/workspace/reimpl_executable" export bash)";
  trap -- '' SIGINT;
  eval "$vars";
  trap - SIGINT;
  return $previous_exit_status;
};
if [[ ";${PROMPT_COMMAND[*]:-};" != *";_direnv_hook;"* ]]; then
  if [[ "$(declare -p PROMPT_COMMAND 2>&1)" == "declare -a"* ]]; then
    PROMPT_COMMAND=(_direnv_hook "${PROMPT_COMMAND[@]}")
  else
    PROMPT_COMMAND="_direnv_hook${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
  fi
fi

